using System.Security.Cryptography;using System.Text;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Options;using QRCoder;using UAF.API.Authorization;using UAF.Domain.Enums;using UAF.Infrastructure.Identity;using UAF.Infrastructure.Persistence;
namespace UAF.API.Endpoints;
public static class VerificationEndpoints{
 public static IEndpointRouteBuilder MapVerificationEndpoints(this IEndpointRouteBuilder app){
 app.MapGet("/api/v1/students/{studentId:guid}/verification-qr",async(Guid studentId,HttpRequest request,UafDbContext db,IOptions<JwtOptions> jwt,IConfiguration config,CancellationToken ct)=>{var student=await db.Students.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==studentId,ct);if(student is null)return Results.NotFound();var signature=Sign($"student:{student.RegistrationNumber}",jwt.Value);var baseUrl=(config["PublicBaseUrl"]??$"{request.Scheme}://{request.Host}").TrimEnd('/');var url=$"{baseUrl}/api/v1/verification/students/{Uri.EscapeDataString(student.RegistrationNumber)}?signature={signature}";using var generator=new QRCodeGenerator();using var data=generator.CreateQrCode(url,QRCodeGenerator.ECCLevel.Q);var png=new PngByteQRCode(data).GetGraphic(8);return Results.File(png,"image/png",$"student-{student.RegistrationNumber}-verification.png");}).RequireAuthorization(AuthorizationPolicies.StudentManagement).WithTags("Student Identity Verification").WithName("GenerateStudentVerificationQr");
 app.MapGet("/api/v1/verification/students/{registrationNumber}",async(string registrationNumber,string signature,UafDbContext db,IOptions<JwtOptions> jwt,CancellationToken ct)=>{if(!Valid($"student:{registrationNumber}",signature,jwt.Value))return Results.NotFound();var student=await(from s in db.Students.AsNoTracking() join p in db.AcademicPrograms.AsNoTracking() on s.AcademicProgramId equals p.Id where s.RegistrationNumber==registrationNumber select new{s.RegistrationNumber,s.FullName,Program=p.Name,Status=s.Status}).SingleOrDefaultAsync(ct);return student is null?Results.NotFound():Results.Ok(new{student.RegistrationNumber,student.FullName,student.Program,status=student.Status.ToString(),verified=true});}).AllowAnonymous().RequireRateLimiting("transcript-verification").WithTags("Public Verification").WithName("VerifyStudentIdentity");
 app.MapGet("/api/v1/admission-documents/{documentId:guid}/verification-link",async(Guid documentId,HttpRequest request,UafDbContext db,IOptions<JwtOptions> jwt,IConfiguration config,CancellationToken ct)=>{var document=await db.AdmissionDocuments.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==documentId,ct);if(document is null)return Results.NotFound();var signature=Sign($"document:{document.Id:N}:{document.Sha256}",jwt.Value);var baseUrl=(config["PublicBaseUrl"]??$"{request.Scheme}://{request.Host}").TrimEnd('/');return Results.Ok(new{url=$"{baseUrl}/api/v1/verification/admission-documents/{document.Id}?signature={signature}",document.Status});}).RequireAuthorization(AuthorizationPolicies.AdmissionsStaff).WithTags("Document Verification").WithName("CreateAdmissionDocumentVerificationLink");
 app.MapGet("/api/v1/verification/admission-documents/{documentId:guid}",async(Guid documentId,string signature,UafDbContext db,IOptions<JwtOptions> jwt,CancellationToken ct)=>{var document=await db.AdmissionDocuments.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==documentId,ct);if(document is null||!Valid($"document:{document.Id:N}:{document.Sha256}",signature,jwt.Value))return Results.NotFound();return Results.Ok(new{verified=document.Status==AdmissionDocumentStatus.Verified,status=document.Status.ToString(),document.DocumentType,document.VerifiedAtUtc});}).AllowAnonymous().RequireRateLimiting("transcript-verification").WithTags("Public Verification").WithName("VerifyAdmissionDocument");
 return app;
 }
 private static string Sign(string value,JwtOptions options){var key=SHA256.HashData(Encoding.UTF8.GetBytes(options.SigningKey+"|UAF-VERIFICATION-V1"));return Convert.ToHexString(HMACSHA256.HashData(key,Encoding.UTF8.GetBytes(value))).ToLowerInvariant();}
 private static bool Valid(string value,string? signature,JwtOptions options){if(string.IsNullOrWhiteSpace(signature)||signature.Length!=64)return false;var expected=Sign(value,options);return CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(expected),Encoding.ASCII.GetBytes(signature.ToLowerInvariant()));}
}
